import { L as LayoutServerHandler } from "../../../../../../chunks/layoutHandler.server.svelte.js";
const POST = async ({ request, params }) => {
  const { id } = params;
  const layout = LayoutServerHandler.layouts.get(id);
  if (!layout) {
    return new Response(
      JSON.stringify({ message: `${id} is not a valid layout.` }),
      { status: 404 }
    );
  }
  try {
    const data = await request.json();
    if (data.layoutName) layout.name = data.layoutName;
    LayoutServerHandler.saveLayouts();
    return new Response(
      JSON.stringify({
        message: "Layout updated successfully",
        layout
      }),
      { status: 200 }
    );
  } catch (error) {
    return new Response(
      JSON.stringify({ message: "Invalid request body" }),
      { status: 400 }
    );
  }
};
export {
  POST
};
